CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,full_name text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),national_id text CHECK(national_id IS NULL OR national_id ~ '^[0-9]{14}$'),requested_account_type text CHECK(requested_account_type IN('citizen','acud','capital_authority','developer')));
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());CREATE POLICY owner_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_portal_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,phone,national_id,requested_account_type) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),coalesce(NEW.raw_user_meta_data->>'phone',''),NEW.raw_user_meta_data->>'national_id',NEW.raw_user_meta_data->>'requested_account_type');RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_portal_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER on_portal_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_portal_profile();
CREATE TYPE public.app_role AS ENUM('admin');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.license_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),kind text NOT NULL DEFAULT 'new' CHECK(kind IN('new','renewal','activity_change','ownership_transfer')),parent_id uuid REFERENCES public.license_requests(id),license_type text NOT NULL CHECK(license_type IN('building','unit')),building_type text,district text,plot_number text NOT NULL,area integer,activity text NOT NULL,owner_name text NOT NULL,fee integer,payment_method text NOT NULL CHECK(payment_method IN('offline','online')),status text NOT NULL DEFAULT 'awaiting_document_review',documents jsonb NOT NULL DEFAULT '[]',issued_at timestamptz,expires_at timestamptz,deleted_at timestamptz,paid_at timestamptz,selected_location jsonb,owner_type text CHECK(owner_type IN('company','individual')),documents_approved_at timestamptz,receipt_path text,receipt_uploaded_at timestamptz,CONSTRAINT license_requests_status_check CHECK(status IN('awaiting_document_review','awaiting_payment','awaiting_payment_review','under_review','issued','rejected')));
GRANT SELECT,INSERT ON public.license_requests TO authenticated;GRANT ALL ON public.license_requests TO service_role;
ALTER TABLE public.license_requests ENABLE ROW LEVEL SECURITY;CREATE POLICY owner_requests_read ON public.license_requests FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE POLICY owner_requests_insert ON public.license_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());CREATE POLICY admin_requests_read ON public.license_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));CREATE POLICY admin_profile_read ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_request_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES public.license_requests(id),actor_id uuid NOT NULL,action text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.admin_request_events TO authenticated;GRANT ALL ON public.admin_request_events TO service_role;
ALTER TABLE public.admin_request_events ENABLE ROW LEVEL SECURITY;CREATE POLICY admin_events_read ON public.admin_request_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));CREATE POLICY admin_events_insert ON public.admin_request_events FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND actor_id=auth.uid());
CREATE TABLE public.support_submissions(id uuid PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),kind text NOT NULL CHECK(kind IN('question','feedback','complaint')),name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 100),email text NOT NULL CHECK(char_length(email)<=255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),phone text NOT NULL DEFAULT '' CHECK(char_length(phone)<=30),complaint_type text NOT NULL DEFAULT '' CHECK(char_length(complaint_type)<=100),message text NOT NULL CHECK(char_length(btrim(message)) BETWEEN 1 AND 5000),CHECK(kind<>'complaint' OR (phone ~ '^[+0-9 ()-]{7,30}$' AND char_length(btrim(complaint_type))>0)));
GRANT INSERT ON public.support_submissions TO anon,authenticated;GRANT SELECT ON public.support_submissions TO authenticated;GRANT ALL ON public.support_submissions TO service_role;
ALTER TABLE public.support_submissions ENABLE ROW LEVEL SECURITY;CREATE POLICY public_support_insert ON public.support_submissions FOR INSERT TO anon,authenticated WITH CHECK(true);CREATE POLICY admin_support_read ON public.support_submissions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.account_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,request_id uuid REFERENCES public.license_requests(id) ON DELETE CASCADE,title text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,event_key text);
GRANT SELECT ON public.account_notifications TO authenticated;GRANT UPDATE(read_at) ON public.account_notifications TO authenticated;GRANT ALL ON public.account_notifications TO service_role;
ALTER TABLE public.account_notifications ENABLE ROW LEVEL SECURITY;CREATE POLICY owner_notifications_read ON public.account_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE POLICY owner_notifications_update ON public.account_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());CREATE INDEX account_notifications_owner_created ON public.account_notifications(user_id,created_at DESC);CREATE UNIQUE INDEX account_notifications_event_key ON public.account_notifications(event_key) WHERE event_key IS NOT NULL;
CREATE TABLE public.environmental_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),project_name text NOT NULL CHECK(char_length(project_name) BETWEEN 2 AND 200),documents jsonb NOT NULL,payment_method text NOT NULL CHECK(payment_method IN('visa_at_office','online')),status text NOT NULL DEFAULT 'under_review',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.environmental_requests TO authenticated;GRANT ALL ON public.environmental_requests TO service_role;
ALTER TABLE public.environmental_requests ENABLE ROW LEVEL SECURITY;CREATE POLICY owner_environment_read ON public.environmental_requests FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE POLICY owner_environment_insert ON public.environmental_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE TABLE public.license_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,mode text NOT NULL DEFAULT 'new' CHECK(mode IN('new','renewal','amendment')),payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=20000),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.license_drafts TO authenticated;GRANT ALL ON public.license_drafts TO service_role;
ALTER TABLE public.license_drafts ENABLE ROW LEVEL SECURITY;CREATE POLICY owner_drafts ON public.license_drafts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());CREATE INDEX license_drafts_owner ON public.license_drafts(user_id,updated_at DESC);
CREATE FUNCTION public.validate_license_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE expected_fee integer;document_count integer; BEGIN
 IF NEW.kind<>'new' THEN IF NEW.parent_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.license_requests WHERE id=NEW.parent_id AND user_id=NEW.user_id AND kind='new') THEN RAISE EXCEPTION 'An owned original request is required';END IF;IF NEW.fee IS NOT NULL THEN RAISE EXCEPTION 'Follow-up fees require review';END IF;
 ELSE IF NEW.parent_id IS NOT NULL OR NEW.owner_type IS NULL THEN RAISE EXCEPTION 'Owner type required';END IF;IF NEW.license_type='building' THEN expected_fee:=CASE NEW.building_type WHEN 'compounds' THEN 33000 WHEN 'hospitals' THEN 16500 WHEN 'schools' THEN 22000 WHEN 'universities' THEN 22000 WHEN 'clubs' THEN 22000 WHEN 'malls' THEN 22000 WHEN 'administrative' THEN 22000 WHEN 'mixed' THEN 21000 WHEN 'fuel' THEN 21000 END;ELSE IF NEW.area IS NULL OR NEW.area<=0 THEN RAISE EXCEPTION 'Valid area required';END IF;expected_fee:=CASE WHEN NEW.area<=50 THEN 4000 WHEN NEW.area<=100 THEN 5000 WHEN NEW.area BETWEEN 151 AND 200 THEN 7000 WHEN NEW.area>200 THEN 11000 END;IF NEW.district NOT IN('DIP','FIN','GOV2','INV','RES','MU','R7','R8') OR NEW.district IS NULL THEN RAISE EXCEPTION 'District required';END IF;END IF;IF expected_fee IS NULL OR NEW.fee IS DISTINCT FROM expected_fee THEN RAISE EXCEPTION 'Fee is unavailable or incorrect';END IF;END IF;
 IF NEW.status<>'awaiting_document_review' OR NEW.payment_method<>'offline' THEN RAISE EXCEPTION 'Applicants must await review and use offline payment';END IF;IF NEW.issued_at IS NOT NULL OR NEW.expires_at IS NOT NULL OR NEW.paid_at IS NOT NULL OR NEW.documents_approved_at IS NOT NULL OR NEW.receipt_path IS NOT NULL THEN RAISE EXCEPTION 'Applicants cannot set review fields';END IF;IF length(trim(NEW.plot_number))=0 OR length(trim(NEW.owner_name))=0 OR length(trim(NEW.activity))=0 THEN RAISE EXCEPTION 'Request details required';END IF;
 IF jsonb_typeof(NEW.documents)<>'array' OR jsonb_array_length(NEW.documents)<>12 THEN RAISE EXCEPTION 'All twelve documents are required';END IF;SELECT count(DISTINCT(d->>'slot')::integer) INTO document_count FROM jsonb_array_elements(NEW.documents)d WHERE (d->>'slot')::integer BETWEEN 1 AND 12 AND d->>'path'=NEW.user_id::text||'/'||NEW.id::text||'/'||(d->>'slot')||'.pdf' AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='license-documents' AND o.name=d->>'path' AND o.metadata->>'mimetype'='application/pdf');IF document_count<>12 THEN RAISE EXCEPTION 'Twelve stored PDF documents required';END IF;
 RETURN NEW; END $$;
CREATE TRIGGER validate_license_request_before_insert BEFORE INSERT ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.validate_license_request();
CREATE FUNCTION public.validate_license_followup() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE original public.license_requests;BEGIN IF NEW.kind='new' THEN RETURN NEW;END IF;SELECT * INTO original FROM public.license_requests WHERE id=NEW.parent_id AND user_id=NEW.user_id AND kind='new';IF NOT FOUND THEN RAISE EXCEPTION 'Owned original request required';END IF;IF NEW.license_type IS DISTINCT FROM original.license_type OR NEW.building_type IS DISTINCT FROM original.building_type OR NEW.district IS DISTINCT FROM original.district OR NEW.plot_number IS DISTINCT FROM original.plot_number OR NEW.area IS DISTINCT FROM original.area THEN RAISE EXCEPTION 'Follow-ups cannot change location or building';END IF;IF NEW.kind<>'activity_change' AND NEW.activity IS DISTINCT FROM original.activity THEN RAISE EXCEPTION 'Only activity amendments may change activity';END IF;IF NEW.kind<>'ownership_transfer' AND (NEW.owner_name IS DISTINCT FROM original.owner_name OR NEW.owner_type IS DISTINCT FROM original.owner_type) THEN RAISE EXCEPTION 'Only ownership transfers may change owner';END IF;RETURN NEW;END $$;
CREATE TRIGGER validate_license_followup_before_insert BEFORE INSERT ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.validate_license_followup();
CREATE FUNCTION public.reject_deleted_license_parent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.license_requests WHERE id=NEW.parent_id AND deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Original request was deleted';END IF;RETURN NEW;END $$;CREATE TRIGGER reject_deleted_license_parent_before_insert BEFORE INSERT ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.reject_deleted_license_parent();
CREATE FUNCTION public.delete_own_license_request(request_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE removed_id uuid;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized';END IF;UPDATE public.license_requests SET deleted_at=now() WHERE id=request_id AND user_id=auth.uid() AND deleted_at IS NULL RETURNING id INTO removed_id;IF removed_id IS NULL THEN RETURN false;END IF;INSERT INTO public.account_notifications(user_id,title,message) VALUES(auth.uid(),'تم حذف الطلب','تم حذف الطلب من قائمة طلباتك.');RETURN true;END $$;REVOKE ALL ON FUNCTION public.delete_own_license_request(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.delete_own_license_request(uuid) TO authenticated;
CREATE POLICY licensing_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='license-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name))='pdf' AND storage.filename(name) NOT LIKE 'receipt%');CREATE POLICY receipt_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='license-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND storage.filename(name) LIKE 'receipt-%' AND lower(storage.extension(name)) IN('pdf','jpg','jpeg','png','webp') AND EXISTS(SELECT 1 FROM public.license_requests r WHERE r.id::text=(storage.foldername(name))[2] AND r.user_id=auth.uid() AND r.status='awaiting_payment' AND r.deleted_at IS NULL));CREATE POLICY licensing_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='license-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));CREATE POLICY unattached_file_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='license-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.license_requests r WHERE r.id::text=(storage.foldername(name))[2] AND r.user_id=auth.uid()));